const t5 = globalThis.t5;

async function main() {
  // 1) 먼저 8월 매출 자료 폴더를 찾는다
  const located = await t5.call("local_locate", { what: "8월 매출 자료", depth: 5 });
  if (!located || !located.best || !located.best.path) {
    console.log({ ok:false, error:"8월 매출 자료 폴더를 찾지 못했습니다." });
    return;
  }

  const basePath = located.best.path;

  // 2) 폴더 안의 파일 목록 확인
  const list = await t5.call("local_file", { action:"list", path: basePath, limit: 200 });
  const items = (list && list.items) ? list.items : [];

  // 3) 초안/백업 제외하면서 엑셀·CSV 후보만 필터링
  const excludeKeywords = ["초안", "draft", "백업", "backup", "사본", "copy", "old", "tmp", "임시"]; // 이름에 들어가면 제외
  const includeExts = [".xlsx", ".xls", ".csv"]; // 매출 계산용 후보

  const candidates = items.filter(it => {
    if (it.kind !== "file") return false;
    const name = it.name.toLowerCase();
    // 초안/백업/임시 제외
    if (excludeKeywords.some(k => name.includes(k))) return false;
    // 임시 엑셀(~$) 제외
    if (name.startsWith("~$")) return false;
    return includeExts.some(ext => name.endsWith(ext));
  });

  if (candidates.length === 0) {
    console.log({ ok:false, error:"8월 매출 자료 폴더 내에 사용할 수 있는 엑셀/CSV 파일 후보가 없습니다.", basePath, allItems:items.map(i=>({name:i.name, kind:i.kind})) });
    return;
  }

  // 4) 각 후보 파일을 읽어서 온라인/매장/배달 매출 열을 찾고 합계를 계산
  const channelKeywords = {
    online: ["온라인", "online", "웹", "쇼핑몰"],
    offline: ["매장", "오프라인", "store"],
    delivery: ["배달", "delivery", "요기요", "배민", "쿠팡이츠"]
  };

  let perFile = [];

  for (const file of candidates) {
    const fullPath = basePath + "/" + file.name;
    const read = await t5.call("local_file", { action:"read", path: fullPath, limit: 50000 });
    if (!read || !read.table || !read.table.columns || !read.table.rows) continue;

    const cols = read.table.columns; // 열 이름 배열
    const rows = read.table.rows;   // 2차원 배열 [row][col]

    // 매출 금액이 담긴 열 후보 찾기 ("매출", "금액", "Total" 등 포함)
    const valueColIndex = cols.findIndex(c => /매출|금액|합계|total/i.test(c));
    if (valueColIndex === -1) continue;

    // 채널 구분 열 후보 ("채널", "구분", "유형" 등)
    const channelColIndex = cols.findIndex(c => /채널|구분|유형|타입/i.test(c));

    let sums = { online:0, offline:0, delivery:0 };

    for (const row of rows) {
      const rawVal = row[valueColIndex];
      const num = typeof rawVal === "number" ? rawVal : parseFloat(String(rawVal).replace(/,/g, ""));
      if (!isFinite(num)) continue;

      if (channelColIndex === -1) {
        // 채널 열이 없으면 스킵 (이 파일은 구조가 안 맞는 걸로 본다)
        continue;
      }

      const ch = String(row[channelColIndex] ?? "");
      const chLower = ch.toLowerCase();

      let assigned = false;
      if (channelKeywords.online.some(k => ch.includes(k) || chLower.includes(k))) {
        sums.online += num; assigned = true;
      }
      if (channelKeywords.offline.some(k => ch.includes(k) || chLower.includes(k))) {
        sums.offline += num; assigned = true;
      }
      if (channelKeywords.delivery.some(k => ch.includes(k) || chLower.includes(k))) {
        sums.delivery += num; assigned = true;
      }

      // 채널 텍스트가 모호하면 일단 무시 (자동 분류 오차 방지)
      if (!assigned) continue;
    }

    perFile.push({ file: fullPath, sums });
  }

  if (perFile.length === 0) {
    console.log({ ok:false, error:"후보 파일들을 열어 봤지만, 온라인/매장/배달 채널별 매출을 계산할 수 있는 구조를 찾지 못했습니다.", basePath, candidates:candidates.map(c=>c.name) });
    return;
  }

  // 5) 파일별 합계를 합산
  let total = { online:0, offline:0, delivery:0 };
  for (const pf of perFile) {
    total.online += pf.sums.online;
    total.offline += pf.sums.offline;
    total.delivery += pf.sums.delivery;
  }

  // 6) 사용자가 말한 배달 환불 2만원을 결과에만 반영 (원본 파일은 그대로)
  const adjusted = {
    online: total.online,
    offline: total.offline,
    // 배달에서 20,000 차감 (원화 기준)
    delivery_before_refund: total.delivery,
    delivery_after_refund: total.delivery - 20000
  };

  const grandTotalBefore = total.online + total.offline + total.delivery;
  const grandTotalAfter = adjusted.online + adjusted.offline + adjusted.delivery_after_refund;

  console.log({
    ok:true,
    basePath,
    perFile,
    totalBeforeRefund: total,
    totalAfterRefund: {
      online: adjusted.online,
      offline: adjusted.offline,
      delivery: adjusted.delivery_after_refund
    },
    grandTotalBefore,
    grandTotalAfter,
    refundApplied: 20000
  });
}

main().catch(err => console.log({ ok:false, error:String(err) }));

